import "./InputForm.css";
import Card from "./Card";
import React, { useState } from "react";
import ErrorModel from "./ErrorModel";
const InputForm = (props) => {
  const [enterdUsername, setEnteredUsername] = useState("");
  const [enterdAge, setEnteredAge] = useState("");
    const[erroe]= useState();

  const submitForm = (event) => {
    event.preventDefault();
    if(enterdUsername.trim().length===0 || enterdAge.trim().length===0){
        return;
    }
    if(+enterdAge<1){
        return;
    }
     props.onAddUser(enterdUsername,enterdAge);
    setEnteredUsername("");
    setEnteredAge("");
  };

  const usernameChangeHandler = (event) => {
    setEnteredUsername(event.target.value);
  };

  const ageChangeHandler = (event) => {
    setEnteredAge(event.target.value);
  };

  return (
    <div>
    <ErrorModel title="An error Occured!" message="something went wrong !"></ErrorModel>
    
    <Card className="input">
      <form className="input" onSubmit={submitForm}>
        <label htmlFor="username">Username</label>
        <input
          type="text"
          id="username"
          value={enterdUsername}
          onChange={usernameChangeHandler}
        ></input>

        <label htmlFor="age">Age(Years)</label>
        <input
          type="number"
          id="age"
          value={enterdAge}
          onChange={ageChangeHandler}
        ></input>

        <button type="submit">Add User</button>
      </form>
    </Card>
    </div>
  );
};
export default InputForm;
